<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
const tasks = ref([]), error = ref(''), selected = ref(null), loading = ref(''), artifacts = ref([]), comparison = ref(null), health = ref(null), runContext = ref(null), runSteps = ref([])
const policyData = ref(null), policyWork = ref(null), policyMessage = ref(''), showPolicy = ref(false), policyReviewNote = ref(''), reviewContext = ref(null), reviewDecisionNote = ref('')
const vocState = ref(null), proposals = ref([]), currentProposal = ref(''), showImprovements = ref(false), feedbackReason = ref('누락'), challenger = ref('challenger-v2'), actionBusy = ref(''), improvementMessage = ref('')
const dataset = ref('v1'), modelMode = ref('MOCK'), omitDocument = ref(false), history = ref([]), leftRun = ref(''), rightRun = ref('')
const base = import.meta.env.VITE_API_BASE || 'http://localhost:8000/api'
function sameSource(a,b) { return !!a && !!b && a.document_id===b.document_id && a.pinned_version===b.pinned_version && a.status===b.status }
function reportIsCurrent(artifact) { return !!vocState.value && artifact.content.method_version===vocState.value.method.active_method_id && sameSource(runContext.value?.manifest?.source_dependency,vocState.value.source_dependency) }
function proposalIsCurrent(proposal) { return !!vocState.value && proposal.champion_state_version===vocState.value.method.version && sameSource(proposal.source_dependency_snapshot,vocState.value.source_dependency) && (proposal.status!=='PROPOSED' || proposal.results?.evaluator_version==='voc-classifier-eval-v2') }
async function refresh() {
  try { const [r,h] = await Promise.all([fetch(`${base}/tasks`),fetch(`${base}/health`)]); if (!r.ok || !h.ok) throw Error('API 응답 오류'); tasks.value = await r.json(); health.value=await h.json(); if (selected.value) await detail(selected.value.work.work_id); await Promise.all([loadPolicy(),loadImprovements()]); error.value = '' }
  catch { error.value = 'API에 연결할 수 없습니다. 서비스 상태를 확인해 주세요.' }
}
async function run(task) {
  loading.value = task.task_id
  try {
    const snapshot = task.task_id === 'TASK-001' ? {source:'dashboard',dataset_version:dataset.value,model_mode:modelMode.value,omit_document:omitDocument.value} : {source:'dashboard'}
    const r = await fetch(`${base}/tasks/${task.task_id}/run`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),input_snapshot:snapshot})})
    if (!r.ok) throw Error('작업을 등록하지 못했습니다.')
    const data = await r.json(); await refresh(); await detail(data.work_id)
  } catch(e) { error.value = e.message } finally { loading.value = '' }
}
async function detail(id) { try { const r = await fetch(`${base}/work/${id}`); if (!r.ok) throw Error(); const data = await r.json(); selected.value = data; const latest = data.runs.at(-1); if(latest){const [a,ctx]=await Promise.all([fetch(`${base}/runs/${latest.run_id}/artifacts`),fetch(`${base}/runs/${latest.run_id}`)]); if(!a.ok || !ctx.ok) throw Error(); artifacts.value=await a.json(); const run=await ctx.json(); runContext.value=run.context; runSteps.value=run.steps || []}else{artifacts.value=[];runContext.value=null;runSteps.value=[]} } catch { error.value = '작업 이력을 불러오지 못했습니다.' } }
async function retry() { try { const id=selected.value.work.work_id; const r=await fetch(`${base}/work/${id}/retry`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})}); if (!r.ok) throw Error(); await detail(id); await refresh() } catch { error.value='재시도를 요청하지 못했습니다.' } }
async function compare() { try { const r=await fetch(`${base}/tasks/TASK-001/runs`); const runs=(await r.json()).filter(x=>x.status==='SUCCEEDED' && x.verdict==='PASS'); if(runs.length<2){error.value='비교하려면 검증을 통과한 TASK-001 실행이 두 개 필요합니다.'; return} history.value=runs; if(!runs.some(x=>x.run_id===leftRun.value)) leftRun.value=runs[1].run_id; if(!runs.some(x=>x.run_id===rightRun.value)) rightRun.value=runs[0].run_id; const q=new URLSearchParams({left:leftRun.value,right:rightRun.value}); const result=await fetch(`${base}/tasks/TASK-001/compare?${q}`); if(!result.ok) throw Error(); comparison.value=await result.json(); error.value='' } catch {error.value='실행 결과를 비교하지 못했습니다.'} }
async function loadPolicy() { const r=await fetch(`${base}/policies/POLICY-VOC`); if(!r.ok) throw Error('정책 데이터를 불러오지 못했습니다.'); policyData.value=await r.json(); const root=policyData.value.latest_event?.root_work_id; if(root){const response=await fetch(`${base}/policy-work/${root}`); if(!response.ok) throw Error('변경 이력을 불러오지 못했습니다.'); policyWork.value=await response.json()} }
async function emitPolicyChange() { loading.value='TASK-002'; try { if(!policyData.value) await loadPolicy(); const [before,after]=policyData.value.versions; const response=await fetch(`${base}/events/document.updated`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_id:crypto.randomUUID(),document_id:before.document_id,old_version:before.version,new_version:after.version,old_sha256:before.sha256,new_sha256:after.sha256})}); if(!response.ok){const body=await response.json(); throw Error(body.detail || '이벤트를 등록하지 못했습니다.')} const result=await response.json(); policyMessage.value=result.created?'변경 이벤트를 등록했습니다.':'이미 처리한 변경으로 기존 작업을 불러왔습니다.'; showPolicy.value=true; await refresh() } catch(e){error.value=e.message} finally {loading.value=''} }
async function recheckPolicy() { if(!policyWork.value) return; actionBusy.value='policy'; try { const id=policyWork.value.work.work_id; const action=policyWork.value.work.status==='COMMITTED'?'revalidate':'retry'; const r=await fetch(`${base}/work/${id}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})}); const result=await r.json(); if(!r.ok) throw Error(result.detail||'재검증을 요청하지 못했습니다.'); policyMessage.value='같은 작업에 새 검증 시도를 요청했습니다.'; await refresh() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
async function savePolicyNote() { if(!policyWork.value?.artifact || !policyReviewNote.value.trim()) return; actionBusy.value='policy-note'; try { const r=await fetch(`${base}/policy-work/${policyWork.value.work.work_id}/review-notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),artifact_id:policyWork.value.artifact.artifact_id,note:policyReviewNote.value.trim()})}); const data=await r.json(); if(!r.ok) throw Error(data.detail||'검토 메모를 기록하지 못했습니다.'); policyReviewNote.value=''; policyMessage.value='검토 메모를 기록했습니다. 규정 상태는 변경되지 않습니다.'; await refresh() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
async function retryPolicyFollowup(node) { actionBusy.value='policy-followup'; try { const r=await fetch(`${base}/work/${node.work_id}/retry`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})}); const data=await r.json(); if(!r.ok) throw Error(data.detail||'후속 작업 재시도를 요청하지 못했습니다.'); policyMessage.value='같은 후속 작업에 새 실행을 요청했습니다.'; await refresh() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
function reviewInputsCurrent() { const p=policyWork.value, ctx=reviewContext.value?.context; if(!p || !ctx || p.followups[3]?.status!=='WAITING_APPROVAL') return false; const ids=[p.work.accepted_artifact_id,...p.followups.slice(0,3).map(n=>n.artifact_id)]; return ctx.stages.every((stage,i)=>stage.artifact_id===ids[i]) && ctx.method_state_version===vocState.value?.method.version }
async function loadReviewContext() { if(!policyWork.value) return; actionBusy.value='review-context'; try { const r=await fetch(`${base}/policy-work/${policyWork.value.work.work_id}/review-context`); const data=await r.json(); if(!r.ok || !data.ready) throw Error('선행 검사나 원천이 준비되지 않았습니다. 상태를 확인한 뒤 다시 불러오세요.'); reviewContext.value=data; policyMessage.value='현재 검토 근거를 불러왔습니다.' } catch(e){reviewContext.value=null;error.value=e.message} finally {actionBusy.value=''} }
async function decidePolicyReview(decision) { if(!reviewInputsCurrent() || !reviewDecisionNote.value.trim()) return; actionBusy.value='review-decision'; try { const r=await fetch(`${base}/policy-work/${policyWork.value.work.work_id}/review-decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),context_sha256:reviewContext.value.context_sha256,decision,note:reviewDecisionNote.value.trim()})}); const data=await r.json(); if(!r.ok) throw Error('근거가 바뀌었거나 기록할 수 없습니다. 검토 대상을 다시 불러오세요.'); reviewContext.value=null; reviewDecisionNote.value=''; policyMessage.value='사용자의 검토 판단을 기록했습니다. 정책 적용은 수행하지 않았습니다.'; await refresh() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
async function reopenPolicyReview() { actionBusy.value='review-reopen'; try { const r=await fetch(`${base}/policy-work/${policyWork.value.work.work_id}/review-reopen`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})}); if(!r.ok) throw Error('재검토를 열지 못했습니다.'); reviewContext.value=null; policyMessage.value='이전 기록을 보존하고 다시 검토하도록 열었습니다.'; await refresh() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
async function loadImprovements() { const [state,list]=await Promise.all([fetch(`${base}/voc/state`),fetch(`${base}/improvements`)]); if(!state.ok || !list.ok) throw Error('개선 상태를 불러오지 못했습니다.'); vocState.value=await state.json(); proposals.value=await list.json(); if(challenger.value===vocState.value.method.active_method_id) challenger.value='challenger-regressed'; if(!currentProposal.value && proposals.value.length) currentProposal.value=proposals.value[0].proposal_id }
async function createFeedback(artifact, recommendation) { actionBusy.value='feedback'; try { const r=await fetch(`${base}/feedback`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),artifact_id:artifact,recommendation_id:recommendation,reason:feedbackReason.value,challenger_version:challenger.value})}); const data=await r.json(); if(!r.ok) throw Error(data.detail||'피드백을 등록하지 못했습니다.'); currentProposal.value=data.proposal_id; showImprovements.value=true; improvementMessage.value='피드백을 기록하고 개선안을 만들었습니다.'; await loadImprovements() } catch(e){error.value=e.message} finally {actionBusy.value=''} }
async function improvementAction(proposal, action) { actionBusy.value=action; try {const r=await fetch(`${base}/improvements/${proposal}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})}); const data=await r.json(); if(!r.ok) throw Error(data.detail||'요청을 처리하지 못했습니다.'); improvementMessage.value={evaluate:'동일 평가셋에서 두 방법을 비교했습니다.',apply:'사용자가 새 분석 방법을 적용했습니다.',reject:'개선안을 기각했습니다.',rollback:'이전 분석 방법으로 되돌렸습니다.'}[action]; await loadImprovements()} catch(e){error.value=e.message} finally {actionBusy.value=''} }
let timer
onMounted(() => { refresh(); timer = setInterval(refresh, 3000) })
onUnmounted(() => clearInterval(timer))
</script>
<template>
  <div class="shell">
    <aside><div class="brand"><span class="brand-mark">W</span><span>WORK<br><b>OS</b></span></div><div class="nav-label">WORKSPACE</div><div class="nav-active">◫ <span>업무 현황</span></div><div class="aside-bottom"><span class="dot"></span> LOCAL WORKSPACE<br><small>v0.1 · kernel foundation</small></div></aside>
    <main><header><span>WORKSPACE / OVERVIEW</span><span class="badge">● &nbsp; DEMO DATA</span></header>
      <div class="heading"><div><div class="eyebrow">WORK, IN CONTEXT <span> / 01</span></div><h1>업무 현황<span>.</span></h1><p>실행보다 오래 남는 업무. 계약과 실행 이력을 한곳에서 확인합니다.</p></div><div class="count"><strong>03</strong><span>등록된 업무<br>WORK DEFINITIONS</span></div></div>
      <div class="notice"><b>DEMO DATA</b><span>시장·규정·VOC는 가상 자료입니다. TASK-001의 LIVE LLM은 해석만 실제 모델로 생성합니다. 규정 변경 후속 작업과 검토 이력을 확인할 수 있으며, VOC 점수는 데모 평가셋 결과입니다. 검색: {{ health?.search?.mode || '확인 중' }} · {{ health?.search?.status || '확인 중' }}.</span></div>
      <p v-if="error" class="error" role="alert">{{ error }}</p>
      <div class="section-title"><div><span>01 / </span>업무 목록</div><small>ACTIVE DEFINITIONS</small></div>
      <div class="cards"><article v-for="(task,i) in tasks" :key="task.task_id"><div class="card-top"><span>{{ task.task_id }} <i> / V{{ task.version }}</i></span><span class="index">0{{ i+1 }}</span></div><h2>{{ task.name }}</h2><p class="objective">{{ task.objective }}</p><div class="meta"><div><span>TRIGGER</span><b>{{ task.trigger_type === 'CRON' ? task.schedule + ' · Asia/Seoul' : task.event_filter }}</b></div><div><span>최근 작업</span><b>{{ task.status || '아직 실행되지 않음' }}</b></div><div><span>최근 실행</span><b>{{ task.run_status || '—' }}</b></div></div><div class="card-verification"><div class="verification-heading"><b>최근 검증 이력</b><small>최근 5회 · 최신순</small></div><p v-if="!task.recent_verifications?.length" class="verification-empty">아직 실행 이력이 없습니다.</p><div v-for="entry in task.recent_verifications" :key="entry.run_id" class="verification-row"><span :class="entry.verdict==='PASS' ? 'verdict-pass' : (entry.verdict==='FAIL' || entry.run_status==='FAILED' ? 'verdict-fail' : '')">{{ entry.verdict || (entry.run_status==='FAILED' ? '실행 실패' : '검증 전') }}</span><span>Task v{{ entry.task_version }} · {{ entry.suite_version || entry.run_status }}<template v-if="entry.checks_total"> · 검사 {{ entry.checks_passed }}/{{ entry.checks_total }}</template></span><small v-if="entry.is_current">채택됨</small><small v-else-if="entry.verdict==='PASS'">이전 기록</small></div><p class="verification-scope">검사 통과 수는 해당 버전의 형식·출처 등 결정론적 검사입니다. 서로 다른 검사 버전의 점수를 직접 비교하거나 의미적 품질로 해석할 수 없습니다.</p></div><p class="card-systems">DB · PostgreSQL 연결됨 &nbsp; / &nbsp; Search · {{ health?.search?.mode || '확인 중' }} {{ health?.search?.status || '확인 중' }}</p><div v-if="task.task_id==='TASK-001'" class="controls"><label>데이터 버전 <select v-model="dataset"><option value="v1">v1 · USD/KRW 1,350</option><option value="v2">v2 · USD/KRW 1,380</option></select></label><label>해석 생성 <select v-model="modelMode"><option value="MOCK">MOCK</option><option value="LIVE_LLM">LIVE LLM</option></select></label><label class="checkbox"><input type="checkbox" v-model="omitDocument"> 첫 시도에 출처 누락 테스트</label></div><div v-if="task.task_id==='TASK-002' && policyData" class="policy-preview"><b>POLICY-VOC · v1 → v2</b><span>연결된 업무: {{ policyData.dependencies.map(d=>d.task_id).join(', ') }}</span><span>상태: {{ policyData.dependencies.map(d=>d.status).join(', ') }}</span><button class="secondary" @click="showPolicy=true">규정과 영향 보기 →</button></div><div v-if="task.task_id==='TASK-003' && vocState" class="policy-preview"><b>현재 분석 방법 · {{ vocState.method.active_method_id }}</b><span>규정 상태 · {{ vocState.source_dependency?.status || '미등록' }}</span><button class="secondary" @click="showImprovements=true">개선 이력 보기 →</button></div><p v-if="task.error" class="failure">{{ task.error }}</p><div class="actions"><button v-if="task.task_id==='TASK-002'" @click="emitPolicyChange" :disabled="loading==='TASK-002'">{{ loading==='TASK-002'?'등록 중…':'변경 이벤트 발생 ↗' }}</button><button v-else @click="run(task)" :disabled="loading === task.task_id">{{ loading === task.task_id ? '등록 중…' : '실행 요청 ↗' }}</button><button v-if="task.work_id && task.task_id!=='TASK-002'" class="secondary" @click="detail(task.work_id)">이력 보기 →</button><button v-if="task.task_id==='TASK-001'" class="secondary" @click="compare">최근 결과 비교 →</button></div></article></div>
      <section v-if="comparison" class="detail"><div class="section-title"><div><span>02 / </span>검증 통과 결과 비교</div><button class="close" @click="comparison=null">닫기 ×</button></div><div class="compare-controls"><label>이전 <select v-model="leftRun" @change="compare"><option v-for="r in history" :key="r.run_id" :value="r.run_id">보고서 v{{ r.artifact_version }} · {{ r.content.dataset_version }} · {{ r.content.model_mode }}</option></select></label><label>이후 <select v-model="rightRun" @change="compare"><option v-for="r in history" :key="r.run_id" :value="r.run_id">보고서 v{{ r.artifact_version }} · {{ r.content.dataset_version }} · {{ r.content.model_mode }}</option></select></label></div><p class="detail-id">{{ comparison.left_dataset }} → {{ comparison.right_dataset }} · DEMO DATA</p><div v-for="item in comparison.changes" :key="item.symbol" class="run"><b>{{ item.symbol }}</b><span>{{ item.before }} → {{ item.after }}</span><span>변화 {{ item.difference }}</span></div><p class="interpretation"><b>이전 해석 · 의미 검증 안 됨</b><br>{{ comparison.left_interpretation }}</p><p class="interpretation"><b>이후 해석 · 의미 검증 안 됨</b><br>{{ comparison.right_interpretation }}</p></section>
      <section v-if="showPolicy && policyData" class="detail"><div class="section-title"><div><span>03 / </span>규정 변경과 후속 작업</div><button class="close" @click="showPolicy=false">닫기 ×</button></div><p class="detail-id">가상 내부 규정 · DEMO DATA · 법규 해석 아님</p><div class="policy-versions"><div v-for="version in policyData.versions" :key="version.version"><b>POLICY-VOC v{{ version.version }}</b><p v-for="(clause,key) in version.clauses" :key="key"><strong>{{ key }}</strong> {{ clause }}</p><small>SHA-256 {{ version.sha256 }}</small></div></div><p class="policy-impact">영향받는 업무: <b v-for="d in policyData.dependencies" :key="d.task_id">{{ d.task_id }} · {{ d.status }} &nbsp;</b></p><p v-if="policyMessage" class="detail-note">{{ policyMessage }}</p><div v-if="!policyWork" class="detail-note">변경 이벤트를 발생시키면 영향 분석과 후속 작업이 생성됩니다.</div><div v-else><p class="detail-id">이벤트 {{ policyWork.event.event_id }} · 분석 Work {{ policyWork.work.status }} · Run {{ policyWork.run?.status || '대기' }}</p><button v-if="['COMMITTED','REWORK_REQUIRED'].includes(policyWork.work.status)" @click="recheckPolicy" :disabled="!!actionBusy">{{ policyWork.work.status==='COMMITTED' ? '같은 작업 재검증 ↻' : '같은 작업 재시도 ↻' }}</button><div v-if="policyWork.artifact"><p class="detail-note">기존 문서 검색: {{ policyWork.retrieval?.mode || '이전 실행: 미기록' }} · 신규 버전 인덱스: {{ policyWork.followups[1]?.status === 'COMMITTED' ? 'OPENSEARCH 확인됨' : (policyWork.followups[1]?.status || '대기') }}</p><p class="detail-note">검증기 {{ policyWork.artifact.verifier_version }} · {{ policyWork.artifact.verification?.passed ? '조항·출처·DAG 검사 통과' : '검증 실패' }}</p><div v-for="change in policyWork.artifact.content.changes" :key="change.clause_id" class="policy-change"><b>{{ change.clause_id }}</b><span>{{ change.before }} → {{ change.after }}</span><small>{{ change.citations.join(' / ') }}</small></div></div><h3>후속 Work DAG</h3><p class="detail-note">변경 해석, 가상 문서 인덱스와 고정 VOC 사례를 검사합니다. 담당자 검토 상태: {{ policyWork.followups[3]?.status || '대기' }}.</p><ol class="dag"><li v-for="node in policyWork.followups" :key="node.work_id"><span class="dag-index">{{ node.step_no }}</span><div><b>{{ node.title }}</b><small>{{ node.work_id }}</small></div><strong>{{ node.status }}</strong></li></ol></div></section>
      <section v-if="showPolicy && policyWork" class="detail">
        <div class="section-title"><div><span>03A / </span>후속 검사와 검토 메모</div></div>
        <p class="detail-note">분석, 새 문서 버전과 가상 VOC 고정 사례를 검사합니다. 회귀 검사는 정책 내용의 의미적 타당성이나 준법 여부를 평가하지 않습니다.</p>
        <div v-for="node in policyWork.followups.filter(n => n.step_no<=3)" :key="node.work_id" class="run"><b>{{ node.title }}</b><span>{{ node.run_status || 'Run 대기' }} · {{ node.verifier_version || '검사 결과 없음' }}<template v-if="node.step_no===3 && node.verification"><small v-for="suite in node.verification.suite_results" :key="suite.suite_version"><br>{{ suite.suite_version }} · {{ suite.case_count }}건 · 기준 {{ suite.baseline_correct }} / 현재 {{ suite.active_correct }} · 퇴행 {{ suite.regressions.length }}건</small></template><br v-if="node.run_error"><small v-if="node.run_error">{{ node.run_error }}</small></span><a v-if="node.run_id" :href="`${base}/runs/${node.run_id}/artifacts`" target="_blank" rel="noopener noreferrer">검사 근거 ↗</a><button v-if="node.status==='REWORK_REQUIRED'" class="secondary" @click="retryPolicyFollowup(node)" :disabled="!!actionBusy">후속 작업 재시도 ↻</button></div>
        <h3>담당자 검토</h3><p class="detail-note">검토 기록은 사람의 판단 이력입니다. 검토 완료나 보완 요청을 기록해도 정책을 적용하거나 의존 상태를 변경하지 않습니다.</p>
        <button v-if="policyWork.followups[3]?.status==='WAITING_APPROVAL'" @click="loadReviewContext" :disabled="!!actionBusy">현재 검토 대상 불러오기</button><button v-if="policyWork.followups[3]?.status==='COMMITTED'" class="secondary" @click="reopenPolicyReview" :disabled="!!actionBusy">이전 기록을 보존하고 재검토 ↻</button>
        <div v-if="reviewContext" class="review-context"><p class="detail-id">{{ reviewContext.context.previous_document_id }} → {{ reviewContext.context.document_id }} · SHA-256 {{ reviewContext.context.document_sha256 }}</p><p class="detail-note">분석 방법 {{ reviewContext.context.method_id }} · 버전 {{ reviewContext.context.method_state_version }} · {{ reviewContext.context.suites.map(s=>s.suite_version).join(' / ') }}</p><div v-for="stage in reviewContext.context.stages" :key="stage.stage" class="policy-change"><b>{{ stage.stage }} · {{ stage.verifier_version }}</b><small>산출물 {{ stage.artifact_id }} · Evidence {{ stage.evidence_id }}</small></div><p v-if="!reviewInputsCurrent()" class="failure">근거가 변경됐습니다. 현재 검토 대상을 다시 불러오세요.</p><div class="controls"><label>판단 근거 <textarea v-model="reviewDecisionNote" maxlength="1000" rows="3" placeholder="검토한 내용과 판단 근거를 입력하세요"></textarea></label><div class="actions"><button @click="decidePolicyReview('REVIEWED')" :disabled="!!actionBusy || !reviewInputsCurrent() || !reviewDecisionNote.trim()">검토 완료 기록</button><button class="secondary" @click="decidePolicyReview('CHANGES_REQUESTED')" :disabled="!!actionBusy || !reviewInputsCurrent() || !reviewDecisionNote.trim()">보완 요청 기록</button></div></div></div>
        <div v-for="review in policyWork.reviews" :key="review.artifact_id" class="policy-change"><b>{{ review.content.decision==='REVIEWED' ? '검토 완료 기록' : '보완 요청 기록' }} · {{ review.is_current ? '현재 Work 기록' : '이전 기록 · 재검토 필요' }}</b><span>{{ review.content.note }}</span><small>Run {{ review.attempt_no }} · {{ review.created_at }} · 정책 미적용 · <a :href="`${base}/runs/${review.run_id}/artifacts`" target="_blank" rel="noopener noreferrer">검토 근거 ↗</a></small></div>
        <div v-if="policyWork.work.status==='COMMITTED' && policyWork.artifact?.artifact_id===policyWork.work.accepted_artifact_id" class="controls"><label>현재 분석에 남길 메모 <textarea v-model="policyReviewNote" maxlength="1000" rows="3" placeholder="확인이 필요한 내용을 입력하세요"></textarea></label><button @click="savePolicyNote" :disabled="!!actionBusy || !policyReviewNote.trim()">검토 메모 기록</button></div>
        <p class="detail-note">메모는 사용자의 기록이며 승인, 정책 적용 또는 검토 완료 처리가 아닙니다. 참조 상태는 REVIEW_REQUIRED로 유지됩니다.</p>
        <div v-for="note in policyWork.review_notes" :key="note.event_id" class="policy-change"><b>검토 메모 · {{ note.created_at }}</b><span>{{ note.payload.note }}</span><small>분석 산출물 {{ note.payload.artifact_id }}{{ note.payload.artifact_id !== policyWork.work.accepted_artifact_id ? ' · 이전 분석' : '' }}</small></div>
      </section>
      <section v-if="selected" class="detail">
        <div class="section-title"><div><span>04 / </span>실행 이력과 근거</div><button class="close" @click="selected=null">닫기 ×</button></div>
        <p class="detail-id">{{ selected.work.work_id }} · {{ selected.work.status }}</p>
        <div v-if="!selected.runs.length">아직 워커가 실행을 가져오지 않았습니다.</div>
        <div v-for="r in selected.runs" :key="r.run_id" class="run"><b>ATTEMPT {{ r.attempt_no }}</b><span>{{ r.status }} · {{ r.model_id }} · {{ r.agent_version }}</span><span>{{ r.error || '—' }}</span></div>
        <template v-if="selected.runs.length"><h3>최근 실행 단계</h3><p class="detail-note">실행별 LangGraph 기록 · 결과 채택은 별도 검증으로 결정됩니다.</p><div v-if="!runSteps.length" class="detail-note">이 실행에는 단계 기록이 없습니다.</div><div v-for="(step,index) in runSteps" :key="index" class="run"><b>{{ step.node_name }}</b><span>{{ step.status }}{{ step.error_type ? ' · ' + step.error_type : '' }}</span><span>{{ step.graph_version }}</span></div></template>
        <button v-if="selected.work.status==='REWORK_REQUIRED'" @click="retry">같은 작업 재시도 ↻</button>
        <div v-for="artifact in artifacts" :key="artifact.artifact_id" class="artifact">
          <div v-if="artifact.kind==='market_briefing'">
            <p class="detail-id">보고서 v{{ artifact.artifact_version }} · {{ artifact.content.data_mode }} · {{ artifact.content.model_mode }} · {{ artifact.content.dataset_version }}</p>
            <div v-for="n in artifact.content.indicators" :key="n.symbol" class="run"><b>{{ n.symbol }}</b><span>{{ n.previous }} → {{ n.current }} {{ n.unit }}</span><span>{{ n.change }} / {{ n.change_percent }}%</span></div>
            <p class="interpretation"><b>모델 해석 · 의미 검증 안 됨</b><br>{{ artifact.content.interpretation }}</p>
            <p class="detail-note">인용: {{ artifact.content.citations.join(', ') }} · 검색 {{ runContext?.manifest?.retrieval?.mode || '이전 실행: 미기록' }} · <a :href="`${base}/runs/${artifact.run_id}`" target="_blank" rel="noopener noreferrer">원천 스냅샷과 해시 보기 ↗</a></p>
          </div>
          <div v-if="artifact.kind==='voc_report'">
            <p class="detail-id">VOC 보고서 v{{ artifact.artifact_version }} · DEMO DATA · MOCK · {{ artifact.content.method_version }} · 규정 {{ artifact.content.source_review_status }}</p>
            <div class="compare-controls feedback-controls"><label>피드백 사유 <select v-model="feedbackReason"><option>누락</option><option>중복/근거 부족</option></select></label><label>비교할 방법 <select v-model="challenger"><option value="challenger-v2" :disabled="vocState?.method.active_method_id==='challenger-v2'">누락 보완 후보</option><option value="challenger-regressed" :disabled="vocState?.method.active_method_id==='challenger-regressed'">퇴행 후보 테스트</option><option value="challenger-overfit" :disabled="vocState?.method.active_method_id==='challenger-overfit'">별도 회귀셋 차단 후보</option></select></label></div>
            <p v-if="vocState && !reportIsCurrent(artifact)" class="detail-note">분석 방법 또는 참조 규정 상태가 바뀌었습니다. 현재 조건으로 실행한 보고서에서 피드백을 남겨주세요.</p>
            <p v-if="artifact.content.comparison_basis" class="detail-note">이전 추천 비교: 범주 기준 · 의미상 중복 여부는 미판단 · {{ artifact.content.history_as_of }} 기준 <a v-if="runContext?.manifest?.previous_report?.run_id" :href="`${base}/runs/${runContext.manifest.previous_report.run_id}/artifacts`" target="_blank" rel="noopener noreferrer">이전 보고서와 근거 ↗</a><span v-else>· 이전 검증 보고서 없음</span></p>
            <p v-else class="detail-note">이전 Task 버전: 추천 범주 비교 미기록</p>
            <p v-if="artifact.content.retrieval_mode" class="detail-note">가상 서비스 문서는 ID·버전·해시를 확인합니다. 추천의 의미적 적합성은 검증하지 않았습니다.</p>
            <div v-for="rec in artifact.content.recommendations" :key="rec.recommendation_id" class="voc-rec"><div><b>{{ rec.category }} · {{ rec.count }}건</b><p>{{ rec.action }}</p><small>근거 {{ rec.record_ids.join(', ') }}</small><small v-if="rec.document_citations"><br>가상 서비스 문서 {{ rec.document_citations.join(', ') }} · {{ artifact.content.retrieval_mode }}</small><small v-if="rec.comparison"><br>{{ rec.comparison==='SAME_CATEGORY' ? '이전 보고서와 동일 범주' : rec.comparison==='NEW_CATEGORY' ? '이전 보고서에 없는 범주' : '이전 보고서 없음' }}<span v-if="rec.previous_recommendation_id"> · {{ rec.previous_recommendation_id }}</span></small></div><button @click="createFeedback(artifact.artifact_id,rec.recommendation_id)" :disabled="!!actionBusy || !reportIsCurrent(artifact)">이 추천에 피드백 ↗</button></div>
            <p class="detail-note">미분류 {{ artifact.content.unclassified_ids.length }}건: {{ artifact.content.unclassified_ids.join(', ') || '없음' }} · <a :href="`${base}/runs/${artifact.run_id}`" target="_blank" rel="noopener noreferrer">원천 스냅샷 ↗</a></p>
          </div>
          <div v-for="e in artifact.evidence" :key="e.evidence_id" class="detail-note">검증기 {{ e.verifier_version }} · {{ e.result.passed ? '결정론적 검사 통과' : '검증 실패' }} · {{ JSON.stringify(e.result.checks) }}</div>
        </div>
      </section>
      <section v-if="showImprovements && vocState" class="detail">
        <div class="section-title"><div><span>05 / </span>VOC 개선과 평가</div><button class="close" @click="showImprovements=false">닫기 ×</button></div>
        <p class="detail-id">DEMO DATA · MOCK · 현재 방법 {{ vocState.method.active_method_id }} · 규정 상태 {{ vocState.source_dependency?.status || '미등록' }}</p>
        <p class="detail-note">가상의 고정 분류 평가셋에서 비교합니다. 점수는 실제 서비스 성능이 아닙니다. 평가는 운영 방법을 자동으로 바꾸지 않습니다.</p>
        <p v-if="improvementMessage" class="policy-impact">{{ improvementMessage }}</p>
        <p v-if="!proposals.length" class="detail-note">VOC 보고서를 실행한 뒤 추천에 피드백을 남기면 개선안이 생깁니다.</p>
        <template v-else>
          <label class="proposal-select">개선안 선택 <select v-model="currentProposal"><option v-for="p in proposals" :key="p.proposal_id" :value="p.proposal_id">{{ p.status }} · {{ p.reason }} · {{ p.challenger_version }}</option></select></label>
          <div v-for="p in proposals.filter(x=>x.proposal_id===currentProposal)" :key="p.proposal_id" class="proposal">
            <p class="detail-id">{{ p.proposal_id }} · {{ p.status }} · {{ p.changed_component }}</p>
            <p class="detail-note">피드백 {{ p.reason }} · {{ p.recommendation_id }} · 근거 산출물 {{ p.artifact_id }}</p>
            <div class="scorecards" v-if="p.results"><div><small>CHAMPION · {{ p.champion_version }}</small><strong>{{ (p.results.champion_accuracy*100).toFixed(1) }}%</strong><span>{{ p.results.champion_correct }} / {{ p.results.case_count }}건</span></div><div><small>CHALLENGER · {{ p.challenger_version }}</small><strong>{{ (p.results.challenger_accuracy*100).toFixed(1) }}%</strong><span>{{ p.results.challenger_correct }} / {{ p.results.case_count }}건</span></div><div><small>평가 결과 · {{ p.verdict }}</small><strong>{{ p.results.regressions.length + (p.results.regression_suite?.regressions.length || 0) }}</strong><span>전체 퇴행 · 기본셋 개선 {{ p.results.gains.length }}건</span></div></div>
            <div v-if="p.results"><p class="detail-note">동일 평가셋 {{ p.suite_version }} · SHA-256 {{ p.suite_sha256 }} · 검증기 {{ p.results.evaluator_version }}</p><p class="detail-note">퇴행 사례: {{ p.results.regressions.join(', ') || '없음' }} · 개선 사례: {{ p.results.gains.join(', ') || '없음' }}</p><p v-if="p.results.regression_suite" class="detail-note">별도 회귀셋 {{ p.results.regression_suite.suite_version }} · Champion {{ p.results.regression_suite.champion_correct }}/{{ p.results.regression_suite.case_count }} · Challenger {{ p.results.regression_suite.challenger_correct }}/{{ p.results.regression_suite.case_count }} · 퇴행 {{ p.results.regression_suite.regressions.length }}건</p><details class="eval-cases"><summary>24개 평가 사례의 정답과 예측 보기</summary><div v-for="c in p.results.cases" :key="c.case_id">{{ c.case_id }} · 정답 {{ c.expected }} · Champion {{ c.champion_prediction }} · Challenger {{ c.challenger_prediction }}</div></details></div>
            <p v-if="['DRAFT','PROPOSED'].includes(p.status) && !proposalIsCurrent(p)" class="detail-note">현행 방법·참조 규정 또는 평가 기준이 변경되어 이 개선안을 적용할 수 없습니다. 현재 보고서에서 새로 제안해 주세요.</p>
            <div class="actions"><button v-if="p.status==='DRAFT'" @click="improvementAction(p.proposal_id,'evaluate')" :disabled="!!actionBusy || !proposalIsCurrent(p)">동일 평가 실행</button><button v-if="p.status==='PROPOSED'" @click="improvementAction(p.proposal_id,'apply')" :disabled="!!actionBusy || p.verdict!=='PASS' || !proposalIsCurrent(p)">적용</button><button v-if="p.status==='PROPOSED'" class="secondary" @click="improvementAction(p.proposal_id,'reject')" :disabled="!!actionBusy">기각</button><button v-if="p.status==='PROMOTED'" @click="improvementAction(p.proposal_id,'rollback')" :disabled="!!actionBusy || vocState.method.last_proposal_id!==p.proposal_id">이전 방법으로 롤백</button></div>
          </div>
        </template>
      </section>
      <footer>WORK OS <span>LOCAL / P0 FOUNDATION</span></footer>
    </main>
  </div>
</template>
